import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CapsuleGeometry,
    CircleGeometry,
    Color,
    PointLight,
    Vector3,
    Box3,
  } = THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10',
  };

  const root = new Group();
  root.name = config.id ?? 'journal-badge';
  root.userData.handlers = {};

  const resources = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;
  let loadedScene = null;

  const gradientStops = visualSpec.gradientStops ?? [
    colors.surface,
    colors.ink,
  ];

  const stopColor = (stop, fallback) => {
    if (typeof stop === 'string') return stop;
    if (stop && typeof stop.color === 'string') return stop.color;
    return fallback;
  };

  const topColor = new Color(
    stopColor(gradientStops[0], colors.surface),
  );
  const bottomColor = new Color(
    stopColor(gradientStops[gradientStops.length - 1], colors.ink),
  );

  const backdropMaterial = new MeshBasicNodeMaterial();
  const topUniform = uniform(topColor);
  const bottomUniform = uniform(bottomColor);
  const backdropUv = uv();
  backdropMaterial.colorNode = mix(
    bottomUniform,
    topUniform,
    smoothstep(0.0, 1.0, backdropUv.y),
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial,
  );
  backdrop.name = 'journal-badge-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });

  const contactShadow = new Mesh(
    new CircleGeometry(0.9, 48),
    shadowMaterial,
  );
  contactShadow.name = 'journal-badge-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -0.42, -0.18);
  contactShadow.scale.set(1.35, 0.55, 1);
  root.add(contactShadow);
  resources.push(contactShadow);

  const capsuleMaterial = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.62,
    metalness: 0.48,
  });
  capsuleMaterial.emissive = new Color(colors.accent);
  capsuleMaterial.emissiveIntensity = 0.08;

  const capsule = new Mesh(
    new CapsuleGeometry(0.29, 1.18, 8, 24),
    capsuleMaterial,
  );
  capsule.name = 'journal-badge-machined-capsule';
  capsule.rotation.z = Math.PI / 2;
  capsule.position.set(0, 0, -0.06);
  capsule.scale.set(1, 0.72, 0.34);
  root.add(capsule);
  resources.push(capsule);

  const rimLight = new PointLight(colors.accent, 0.78, 3.2, 2);
  rimLight.name = 'journal-badge-accent-rim';
  rimLight.position.set(0.72, 0.3, 0.65);
  root.add(rimLight);
  resources.push(rimLight);

  const fillLight = new PointLight(colors.paper, 0.22, 2.8, 2);
  fillLight.name = 'journal-badge-paper-fill';
  fillLight.position.set(-0.75, 0.15, 0.45);
  root.add(fillLight);
  resources.push(fillLight);

  const entrance = gsap.timeline();
  entrance.fromTo(
    root.position,
    { y: -0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
  );
  entrance.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0,
  );
  timelines.push(entrance);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const result = ctx.primitives[primitive.name](
      root,
      primitive.params ?? {},
    );
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers.hover = (active = true) => {
    if (disposed) return;

    const targetY = active ? 0.15 : 0;
    const targetRotation = active ? -0.035 : 0;

    const hoverTimeline = gsap.timeline();
    hoverTimeline.to(
      root.position,
      { y: targetY, duration: 0.3, ease: 'power2.out' },
      0,
    );
    hoverTimeline.to(
      root.rotation,
      { z: targetRotation, duration: 0.3, ease: 'power2.out' },
      0,
    );
    timelines.push(hoverTimeline);
  };

  root.userData.handlers.click = () => {
    if (disposed) return;

    const pressTimeline = gsap.timeline();
    pressTimeline
      .to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      })
      .to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.32,
        ease: 'back.out(2)',
      });
    timelines.push(pressTimeline);

    ctx.emit('hub-journal.select', {
      nodeId: config.id ?? 'journal-badge',
    });
  };

  const meshUrl = config.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      loadedScene = gltf.scene;
      loadedScene.name = 'journal-badge-gear';

      const bounds = new Box3().setFromObject(loadedScene);
      const size = bounds.getSize(new Vector3());
      const maxDimension = Math.max(size.x, size.y, size.z);

      if (maxDimension > 0) {
        loadedScene.scale.setScalar(0.82 / maxDimension);
      }

      loadedScene.position.set(0, 0, 0.18);
      root.add(loadedScene);
    });
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const item of material) item?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of resources) {
      if (resource.parent) resource.parent.remove(resource);
    }

    loadedScene = null;
    root.clear();
  };

  return root;
}
